import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if user is logged in from localStorage
    const savedUser = localStorage.getItem('farm2home_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const login = (userData) => {
    setUser(userData);
    localStorage.setItem('farm2home_user', JSON.stringify(userData));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('farm2home_user');
  };

  const register = (userData) => {
    // In a real app, this would make an API call
    const newUser = {
      ...userData,
      id: Date.now(),
      createdAt: new Date().toISOString()
    };

    // Save to localStorage (simulating database)
    const users = JSON.parse(localStorage.getItem('farm2home_users') || '[]');
    users.push(newUser);
    localStorage.setItem('farm2home_users', JSON.stringify(users));

    login(newUser);
    return newUser;
  };

  const value = {
    user,
    login,
    logout,
    register,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};
